    return {
        "appointment_id": row["id"],
        "patient_id": row["patient_id"],
        "doctor_id": row["doctor_id"],
        "appointment_date": row["appointment_date"],
        "status": row["status"],
        "priority": row["priority"],
        "created_at": row["created_at"],
